import json, os
HERE = os.path.dirname(os.path.abspath(__file__))
D = (2, -2.2)          # 문 앞
TOP = (-2, 1)          # 언덕 꼭대기
def I(level, time="day", **k):
    d = dict(place="island", time=time, level=level); d.update(k); return d
def cam(typ, fr, to=None, tg=(0, 0, 1), tg2=None, lens=35, deg=30):
    c = dict(type=typ, **{"from": list(fr)}, target=list(tg), lens=lens, deg=deg)
    if to: c["to"] = list(to)
    if tg2: c["target_to"] = list(tg2)
    return c
M = lambda **k: dict(who="만수", **k)
S = lambda **k: dict(who="서연", **k)
